window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[358]={"id":"358","numero":358,"titre":"Pancréatite aiguë","objectifs":[{"id":"358-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la pancréatite aiguë","contenu":"<p>La <span class=\"kw-def\">pancréatite aiguë</span> est une <strong><span class=\"kw-def\">inflammation aiguë du pancréas</span></strong>. Son <span class=\"kw-def\">incidence</span> est de <span class=\"kw-chiffre\">30 pour 100 000</span> chez l'homme et <span class=\"kw-chiffre\">10 pour 100 000</span> chez la femme.</p>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> en trois temps : (1) <span class=\"kw-etio\">agression du parenchyme pancréatique</span> et/ou <span class=\"kw-etio\">obstacle bloquant l'excrétion du suc pancréatique</span> ; (2) <span class=\"kw-def\">activation intra-pancréatique des enzymes</span> (conversion du <span class=\"kw-bio\">trypsinogène en trypsine</span>) libérées en excès ; (3) <span class=\"kw-alerte\">autodigestion pancréatique</span>, aboutissant à une inflammation voire une <span class=\"kw-clinique\">nécrose</span> de la glande et des tissus avoisinants.</p>\n      <p>On distingue <strong>deux formes anatomocliniques</strong>, de <span class=\"kw-def\">pronostic</span> très différent :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Fréquence</th><th><span class=\"kw-def\">Mortalité</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">PA œdémateuse</span></strong> (bénigne)</td><td><span class=\"kw-chiffre\">70-80 %</span></td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">PA nécrosante</span></strong></td><td><span class=\"kw-chiffre\">20-30 %</span></td><td><span class=\"kw-chiffre\">10 %</span> (plus élevée si <span class=\"kw-alerte\">surinfection de nécrose</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-def\">Mortalité</span> globale de la <span class=\"kw-def\">pancréatite aiguë</span> : <span class=\"kw-chiffre\">3-5 %</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 281 — <span class=\"kw-def\">Pancréatite chronique</span></em></p>","frequence":1},{"id":"358-2","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier les situations de gravité immédiate de la pancréatite aiguë","contenu":"<p>La <span class=\"kw-alerte\">forme grave d'emblée</span> se définit par la présence d'une <strong><span class=\"kw-alerte\">défaillance viscérale dès le stade initial</span></strong> de la <span class=\"kw-clinique\">poussée</span>. Elle est <span class=\"kw-chiffre\">rare (15 %)</span> mais sa <span class=\"kw-def\">mortalité</span> atteint <span class=\"kw-chiffre\">&gt; 50 %</span>.</p>\n      <p><strong>Défaillances à reconnaître en <span class=\"kw-alerte\">urgence</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Choc cardiovasculaire</span></li>\n        <li><span class=\"kw-alerte\">SDRA</span> — <span class=\"kw-alerte\">détresse respiratoire aiguë</span></li>\n        <li><span class=\"kw-alerte\">Oligo-anurie / insuffisance rénale aiguë</span></li>\n        <li><span class=\"kw-alerte\">Défaillance neurologique</span></li>\n        <li><span class=\"kw-alerte\">CIVD</span></li>\n      </ul>\n      <p>L'<span class=\"kw-clinique\">insuffisance rénale aiguë</span> survient dans <span class=\"kw-chiffre\">20 %</span> des cas et constitue un <strong>facteur pronostique péjoratif</strong> : <span class=\"kw-chiffre\">75 %</span> fonctionnelle (hypovolémie, <span class=\"kw-alerte\">choc</span>) et <span class=\"kw-chiffre\">25 %</span> organique (<span class=\"kw-clinique\">nécrose</span> tubulaire aiguë).</p>\n      <p>Deux <span class=\"kw-alerte\">signes cutanés</span> traduisent une forme nécrosante <span class=\"kw-etio\">hémorragique</span> — gravité immédiate :</p>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Signe de Grey-Turner</span></strong> : <span class=\"kw-ttt\">infiltration</span> hématique des flancs</li>\n        <li><strong><span class=\"kw-alerte\">Signe de Cullen</span></strong> : <span class=\"kw-ttt\">infiltration</span> hématique péri-ombilicale</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> La PA peut être grave <strong>d'emblée</strong> (<span class=\"kw-alerte\">défaillance</span> multiviscérale initiale) mais aussi s'<span class=\"kw-alerte\">aggraver secondairement</span>, parfois plusieurs jours à semaines après le début — la <span class=\"kw-def\">surveillance</span> ne s'arrête pas à la phase initiale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":0},{"id":"358-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> repose sur l'association <strong><span class=\"kw-clinique\">douleur typique</span> + <span class=\"kw-bio\">lipasémie</span></strong>. La <span class=\"kw-clinique\">douleur pancréatique</span> est présente dans <span class=\"kw-chiffre\">90-100 %</span> des cas — caractéristiques sémiologiques :</p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Siège</td><td><span class=\"kw-clinique\">Épigastrique</span> ; hypochondre gauche ; sus-ombilical</td></tr>\n          <tr><td><span class=\"kw-clinique\">Irradiation</span></td><td><span class=\"kw-clinique\">Postérieure transfixiante</span> ; hémi-ceinture gauche costo-lombaire</td></tr>\n          <tr><td>Type</td><td>Torsion ; arrachement ; <span class=\"kw-clinique\">broiement en coup de poignard</span></td></tr>\n          <tr><td>Début</td><td>Rapidement progressif</td></tr>\n          <tr><td>Horaire</td><td>Aiguë, intense, <span class=\"kw-clinique\">insomniante</span>, durant plusieurs heures à jours</td></tr>\n          <tr><td>Attitude <span class=\"kw-ttt\">antalgique</span></td><td><span class=\"kw-clinique\">Position en chien de fusil</span> (antéflexion du tronc, compression de l'ép<span class=\"kw-chiffre\">iga</span>stre)</td></tr>\n          <tr><td>Facteurs déclenchants</td><td>Alimentation ; <span class=\"kw-etio\">alcool</span> ; certains médicaments</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes associés :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Vomissements</span> (<span class=\"kw-chiffre\">50 %</span>) : alimentaires puis bilieux</li>\n        <li><span class=\"kw-clinique\">Iléus réflexe</span> (<span class=\"kw-chiffre\">30 %</span>) : arrêt des matières et des gaz (rarement complet), météorisme sonore</li>\n        <li>Signes généraux : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span></li>\n        <li><span class=\"kw-clinique\">Défense abdominale</span> possible, diffuse ou localisée à l'ép<span class=\"kw-chiffre\">iga</span>stre</li>\n      </ul>\n      <p><strong>Biologie — la lipasémie :</strong> une <span class=\"kw-clinique\">douleur typique</span> associée à une <strong><span class=\"kw-bio\">lipase &gt; 3N</span></strong> suffit au diagnostic de <span class=\"kw-def\">pancréatite aiguë</span> (aucun autre examen complémentaire n'est alors nécessaire). L'élévation est <span class=\"kw-bio\">précoce</span>, parfois fugace, avec un maximum en <span class=\"kw-chiffre\">24-48 h</span> ; elle peut être <span class=\"kw-alerte\">&lt; 3N si le dosage est réalisé ≥ 48 h</span> après le début des douleurs.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-bio\">lipasémie n'a aucune valeur pronostique</span> : il n'existe pas de corrélation entre le taux de <span class=\"kw-bio\">lipase</span> et la gravité de la PA. Le <span class=\"kw-bio\">dosage de l'amylase</span> doit être <span class=\"kw-ci\">abandonné</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë</em></p>","frequence":6},{"id":"358-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel des douleurs abdominales","contenu":"<p>Devant une <span class=\"kw-clinique\">douleur épigastrique intense</span>, plusieurs diagnostics doivent être discutés. La plupart sont <strong>écartés grâce à la lipasémie</strong> :</p>\n      <table >\n        <thead><tr><th>Diagnostic</th><th>Élément discriminant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Ulcère gastro-duodénal</span> perforé ou non</td><td>ATCD d'<span class=\"kw-clinique\">UGD</span> ; début très brutal ; <span class=\"kw-imagerie\">pneumopéritoine</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Infarctus du myocarde inférieur</span></td><td>Écarté par l'<span class=\"kw-bio\">ECG</span></td></tr>\n          <tr><td><span class=\"kw-def\">Péritonite biliaire</span></td><td>Contracture ; syndrome péritonéal</td></tr>\n          <tr><td><span class=\"kw-alerte\">Infarctus mésentérique</span></td><td>ATCD vasculaire ; signes <span class=\"kw-imagerie\">TDM</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Rupture d'anévrisme de l'aorte abdominale</span></td><td><span class=\"kw-clinique\">Masse</span> battante ; collapsus ; <span class=\"kw-imagerie\">angio-TDM</span></td></tr>\n          <tr><td><span class=\"kw-def\">Pneumopathie</span></td><td><span class=\"kw-clinique\">Douleur abdominale</span> projetée — piège fréquent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-alerte\">pneumopathie</span> (notamment des bases) peut mimer une <span class=\"kw-clinique\">douleur abdominale</span> haute : penser à l'examen pleuropulmonaire et à la <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span> devant toute douleur ép<span class=\"kw-chiffre\">iga</span>strique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span class=\"kw-clinique\">Douleur abdominale</span> aiguë · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 357 — <span class=\"kw-clinique\">Péritonite</span> aiguë · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":1},{"id":"358-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir identifier une complication infectieuse secondaire","contenu":"<p>La <strong><span class=\"kw-alerte\">surinfection de nécrose</span></strong> est la principale complication infectieuse de la <span class=\"kw-def\">pancréatite aiguë</span>.</p>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span> :</strong> <span class=\"kw-etio\">translocation bactérienne</span> depuis le tube digestif vers <span class=\"kw-clinique\">les</span> zones nécrosées — germes d'origine digestive, infection <strong>plurimicrobienne</strong>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td>Contexte</td><td><span class=\"kw-chiffre\">20-40 %</span> des PA nécrosantes ; <span class=\"kw-alerte\">JAMAIS au cours d'une PA œdémateuse</span></td></tr>\n          <tr><td>Gravité</td><td><span class=\"kw-clinique\">Les</span> infections sont responsables de <span class=\"kw-chiffre\">50-80 %</span> des décès</td></tr>\n          <tr><td>Délai</td><td><span class=\"kw-chiffre\">2 à 4 semaines</span> après le début de l'<span class=\"kw-alerte\">hospitalisation</span> (rare <span class=\"kw-clinique\">les</span> 10-15 premiers jours)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations à rechercher :</strong></p>\n      <ul>\n        <li><strong>Clinique :</strong> <span class=\"kw-clinique\">fièvre</span> ; apparition ou majoration d'un <span class=\"kw-clinique\">SRIS</span> ; nouvelles défaillances viscérales</li>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">syndrome inflammatoire / infectieux biologique</span></li>\n        <li><strong>Imagerie :</strong> <span class=\"kw-imagerie\">bulles d'air dans les coulées de nécrose</span> — évocateur de germes <span class=\"kw-etio\">anaérobies</span>, mais inconstant</li>\n      </ul>\n      <p><strong>Conduite à tenir :</strong></p>\n      <ul>\n        <li>Coulée de <span class=\"kw-clinique\">nécrose</span> <strong>non surinfectée</strong> : pas de <span class=\"kw-ttt\">drainage</span>, sauf <span class=\"kw-clinique\">compression biliaire ou digestive symptomatique</span></li>\n        <li>Suspicion de surinfection (<span class=\"kw-alerte\">coulée de nécrose + fièvre</span>) : <span class=\"kw-clinique\">ponction de la coulée</span> + <span class=\"kw-bio\">hémocultures</span></li>\n        <li>Surinfection confirmée : <span class=\"kw-ttt\">antibiothérapie probabiliste à large spectre</span>, adaptée secondairement</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":1},{"id":"358-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments biologiques permettant de suspecter une origine biliaire devant une pancréatite aiguë","contenu":"<p>Plusieurs anomalies biologiques orientent vers une <strong><span class=\"kw-etio\">origine biliaire</span></strong> (cause la plus fréquente avec l'<span class=\"kw-etio\">alcool</span>) :</p>\n      <ul>\n        <li><strong>Pic d'<span class=\"kw-bio\">hypertransaminasémie</span> précoce et très transitoire</strong> (<span class=\"kw-chiffre\">&lt; 48 h</span>) : prédomine sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">ASAT</span> dans les premières <span class=\"kw-chiffre\">24 h</span>, puis sur les <span class=\"kw-bio\">ALAT</span></li>\n        <li>Élévation des <strong>marqueurs de <span class=\"kw-bio\">cholestase</span></strong>, fréquemment associée : <span class=\"kw-bio\">PAL</span> ; <span class=\"kw-bio\">GGT</span> ; <span class=\"kw-bio\">bilirubine</span></li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> de <span class=\"kw-etio\">lithiase biliaire</span></strong> renforçant la suspicion : <span class=\"kw-etio\">femme &gt; 50 ans</span> ; <span class=\"kw-etio\">surcharge pondérale</span> ; <span class=\"kw-etio\">variation pondérale</span> ; <span class=\"kw-etio\">multiparité</span> ; <span class=\"kw-etio\">antécédents familiaux</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le caractère <span class=\"kw-bio\">précoce et fugace</span> du pic de transaminases impose un dosage rapproché : un <span class=\"kw-bio\">bilan hépatique</span> fait trop tardivement peut être normal et faussement rassurant.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":1},{"id":"358-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","contenu":"<p>Deux examens d'imagerie ont des indications et des objectifs distincts :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Quand</th><th>Objectifs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie abdominale</span></strong></td>\n            <td><strong>Systématique</strong>, idéalement <span class=\"kw-chiffre\">&lt; 48 h</span> après le début des douleurs (au-delà : <span class=\"kw-alerte\">sludge vésiculaire</span> induit par le jeûne)</td>\n            <td>Orientation <span class=\"kw-etio\">étiologique</span> : <span class=\"kw-clinique\">lithiase vésiculaire</span> ; dilatation ou lithiase de la VBP. La <span class=\"kw-imagerie\">TDM</span> ne peut PAS s'y substituer (moins performante pour la lithiase biliaire)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span></strong></td>\n            <td><span class=\"kw-alerte\">PAS au diagnostic initial</span> (sous-estime la <span class=\"kw-clinique\">nécrose</span> si trop précoce) ; à différer <span class=\"kw-chiffre\">72-96 h</span> après le début des douleurs</td>\n            <td><span class=\"kw-def\">Score</span> <span class=\"kw-def\">CTSI</span> (<span class=\"kw-def\">diagnostic positif</span> + sévérité) ; recherche de complications : <span class=\"kw-imagerie\">ascite</span>, <span class=\"kw-imagerie\">épanchement pleural</span>, <span class=\"kw-imagerie\">hémorragie</span>, <span class=\"kw-imagerie\">fistule</span>, <span class=\"kw-imagerie\">perforation d'organe creux</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Indications de la <span class=\"kw-imagerie\">TDM</span>, limitées : <span class=\"kw-clinique\">doute diagnostique</span> ; évaluation des <span class=\"kw-alerte\">formes sévères</span> ; évaluation de la <span class=\"kw-alerte\">gravité</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le délai de la <span class=\"kw-imagerie\">TDM</span> se compte <strong>à partir du début des douleurs</strong>, et <span class=\"kw-alerte\">PAS à partir du début de la prise en charge</span>. Faite trop tôt, elle sous-estime l'étendue de la <span class=\"kw-clinique\">nécrose</span>.</div>","frequence":4},{"id":"358-8","rang":"B","rubrique":"Identifier une urgence","titre":"Connaître les éléments de gravité d’une pancréatite aiguë","contenu":"<p>L'évaluation de la gravité associe des éléments cliniques, biologiques et scanographiques :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span> :</strong> l'<span class=\"kw-etio\">obésité</span> est un <span class=\"kw-def\">facteur de risque</span> <strong>indépendant</strong> de gravité</li>\n        <li><strong>Clinique :</strong> la présence d'un <span class=\"kw-clinique\">SRIS</span> est l'un des meilleurs indicateurs pronostiques</li>\n        <li><strong>Biologie :</strong> <strong><span class=\"kw-bio\">CRP &gt; 150 mg/L à J2</span></strong> — marqueur <span class=\"kw-ttt\">biologique</span> le plus fiable pour évaluer la gravité d'une PA</li>\n      </ul>\n      <p><strong>Critères du <span class=\"kw-clinique\">SIRS</span></strong> — association d'<strong><span class=\"kw-chiffre\">≥ 2 critères</span></strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Seuil</th></tr></thead>\n        <tbody>\n          <tr><td>Température</td><td><span class=\"kw-chiffre\">&lt; 36 °C</span> ou <span class=\"kw-chiffre\">&gt; 38 °C</span></td></tr>\n          <tr><td>Fréquence cardiaque</td><td><span class=\"kw-chiffre\">&gt; 90 bpm</span></td></tr>\n          <tr><td>Fréquence respiratoire</td><td><span class=\"kw-chiffre\">&gt; 20/min</span> ou <span class=\"kw-bio\">PaCO₂ &lt; 32 mmHg</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Leucocytes</span></td><td><span class=\"kw-bio\">&gt; 12 G/L</span> ou <span class=\"kw-bio\">&lt; 4 G/L</span> ou <span class=\"kw-chiffre\">&gt; 10 %</span> de formes immatures</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Score</span> CTSI (Balthazar modifié)</strong> — somme inflammation + <span class=\"kw-clinique\">nécrose</span>, sur <span class=\"kw-chiffre\">10 points</span> :</p>\n      <table >\n        <thead><tr><th>Inflammation (sans injection)</th><th>Pts</th><th>Nécrose (avec injection)</th><th>Pts</th></tr></thead>\n        <tbody>\n          <tr><td>Pancréas normal</td><td><span class=\"kw-chiffre\">0</span></td><td>Pas de <span class=\"kw-clinique\">nécrose</span></td><td><span class=\"kw-chiffre\">0</span></td></tr>\n          <tr><td>Élargissement focal ou diffus</td><td><span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-chiffre\">&lt; 30 %</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Infiltration</span> de la graisse péripancréatique</td><td><span class=\"kw-chiffre\">2</span></td><td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-chiffre\">30-50 %</span></td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td>Une collection péripancréatique</td><td><span class=\"kw-chiffre\">3</span></td><td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-chiffre\">&gt; 50 %</span></td><td><span class=\"kw-chiffre\">6</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">≥ 2</span> collections ou bulles d'<span class=\"kw-def\">air</span></td><td><span class=\"kw-chiffre\">4</span></td><td>—</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interprétation :</strong> <span class=\"kw-chiffre\">0-3</span> peu sévère ; <strong><span class=\"kw-alerte\">CTSI ≥ 4</span> = PA sévère</strong> (<span class=\"kw-chiffre\">4-6</span> modérément sévère, <span class=\"kw-chiffre\">7-10</span> grave). La <span class=\"kw-clinique\">nécrose</span> correspond à une <span class=\"kw-imagerie\">absence ou diminution de prise de contraste</span> du pancréas.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> NE sont <strong>PAS</strong> des facteurs pronostiques : la <span class=\"kw-alerte\">douleur</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">vomissements</span>, l'<span class=\"kw-alerte\">iléus</span>, la <span class=\"kw-alerte\">lipasémie</span> et l'<span class=\"kw-alerte\">hyperleucocytose</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"358-9","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’une pancréatite aiguë nécrosante","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/358/tdm-pancreatite-aigue-necrosante.png\" alt=\"TDM abdomino-pelvienne coupe axiale injectée au temps portal : pancréatite aiguë nécrosante avec parenchyme non rehaussé et collections liquidiennes\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> abdomino-pelvienne, coupe axiale, injection au temps portal. La <span class=\"kw-clinique\">nécrose</span> pancréatique correspond au parenchyme non rehaussé ; le pancréas sain se rehausse. Présence de collections liquidiennes. <span class=\"kw-def\">Score</span> CTSI 10 (nécrose &gt;<span class=\"kw-chiffre\"> 50 %</span> = 6 pts + au moins 2 collections liquidiennes = 4 pts). Source : fiche source EDN item 358.</figcaption>\n      </figure>\n      <p><strong>Lecture de la <span class=\"kw-imagerie\">TDM</span> :</strong> la <span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> est réalisée en <strong>coupe axiale</strong> avec <strong>injection au temps portal</strong>.</p>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Nécrose pancréatique</span></strong> : zone de <span class=\"kw-imagerie\">parenchyme non rehaussé</span> après injection. Le pancréas sain, lui, <span class=\"kw-imagerie\">se rehausse</span> normalement (queue du pancréas visible).</li>\n        <li><strong><span class=\"kw-imagerie\">Collections liquidiennes</span></strong> péripancréatiques, témoins de la sévérité.</li>\n        <li>Repères de voisinage : <span class=\"kw-imagerie\">vésicule biliaire</span>, <span class=\"kw-imagerie\">foie</span>.</li>\n      </ul>\n      <p>Exemple chiffré de la figure : <strong><span class=\"kw-def\">score</span> <span class=\"kw-def\">CTSI 10</span></strong> = <span class=\"kw-clinique\">nécrose</span> du parenchyme <span class=\"kw-chiffre\">&gt; 50 %</span> (<span class=\"kw-chiffre\">6 pts</span>) + au moins 2 collections liquidiennes (<span class=\"kw-chiffre\">4 pts</span>) — <span class=\"kw-alerte\">pancréatite aiguë nécrosante</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Sur une <span class=\"kw-imagerie\">TDM</span> injectée, la <span class=\"kw-imagerie\">nécrose</span> se définit par l'<strong>absence de rehaussement</strong> du parenchyme — c'est le signe direct qui distingue la PA nécrosante de la PA œdémateuse.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/acute-pancreatitis","label":"Radiopaedia : Acute pancreatitis"},{"href":"https://www.imaios.com/fr/e-cases/imaios/classifications/pancreatite-aigue","label":"IMAIOS e-Anatomy — Pancreatite aigue"},{"href":"https://radiopaedia.org/articles/acute-peripancreatic-fluid-collection","label":"Radiopaedia : Acute peripancreatic fluid collection"}]},{"id":"358-10","rang":"A","rubrique":"Étiologies","titre":"Savoir identifier les deux principales causes de pancréatite aiguë","contenu":"<p>Deux causes représentent à elles seules <strong><span class=\"kw-chiffre\">80 %</span></strong> des étiologies de <span class=\"kw-def\">pancréatite aiguë</span> :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Part</th><th><span class=\"kw-def\">Terrain</span> et arguments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Lithiase biliaire</span></strong></td>\n            <td><span class=\"kw-chiffre\">40 %</span></td>\n            <td>Migration d'un calcul biliaire dans le <span class=\"kw-clinique\">cholédoque / la VBP</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Alcool</span></strong></td>\n            <td><span class=\"kw-chiffre\">40 %</span></td>\n            <td>Consommation chronique et prolongée. <span class=\"kw-def\">Terrain</span> : homme ~<span class=\"kw-chiffre\">40 ans</span>, <span class=\"kw-etio\">alcool</span> <span class=\"kw-chiffre\">&gt; 100 g/jour</span> (≈ 10 verres standard) depuis <span class=\"kw-chiffre\">&gt; 10 ans</span> ; le <span class=\"kw-etio\">tabac</span> est un cofacteur de sévérité</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Origine alcoolique — signes biologiques évocateurs :</strong> ↑ <span class=\"kw-bio\">VGM</span> ; ↑ <span class=\"kw-bio\">γ-GT</span> ; cytolyse prédominant sur <span class=\"kw-bio\">ASAT &gt; ALAT</span>. La PA correspond à une <span class=\"kw-clinique\">poussée</span> inaugurale de <span class=\"kw-def\">pancréatite chronique calcifiante</span> dans <span class=\"kw-chiffre\">90 %</span> des cas (calcifications souvent absentes aux premières poussées).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 277 — Lithiase biliaire</em></p>","frequence":2},{"id":"358-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les autres causes de pancréatite aiguë","contenu":"<p>En dehors de l'<span class=\"kw-etio\">alcool</span> et de la lithiase biliaire, de nombreuses étiologies plus rares doivent être connues :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Tumorale</span></strong></td><td><span class=\"kw-alerte\">1ʳᵉ cause à évoquer &gt; 50 ans</span> si PA non alcoolique et non biliaire : <span class=\"kw-def\">adénocarcinome</span> (le plus fréquent), <span class=\"kw-def\">TIPMP</span>. Imagerie : signes directs (obstacle) ou indirects (dilatation segmentaire des canaux)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Hypertriglycéridémie</span></strong></td><td>Hyperchylomicronémies primitives ; un taux de <span class=\"kw-bio\">TG &gt; 10 mmol/L</span> est nécessaire pour l'incriminer</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Hypercalcémie</span></strong></td><td><span class=\"kw-bio\">&gt; 3 mmol/L</span>, quelle qu'en soit la cause — responsable de <span class=\"kw-chiffre\">1 %</span> des PA</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Infectieuse</span></strong></td><td>Virus : oreillons, <span class=\"kw-bio\">CMV</span>, <span class=\"kw-bio\">VIH</span>, <span class=\"kw-def\">hépatite</span> B, <span class=\"kw-etio\">entérovirus</span> ; parasitoses (migration des larves par le sphincter d'Oddi) : ascaridiose, distomatose, hydatidose</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Post-opératoire / post-traumatique</span></strong></td><td>Après <span class=\"kw-ttt\">chirurgie</span> biliaire ou gastrique, ou <span class=\"kw-def\">CPRE</span> (<span class=\"kw-chiffre\">5 %</span> des cas) ; traumatismes fermés avec <span class=\"kw-alerte\">choc</span> ép<span class=\"kw-chiffre\">iga</span>strique</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Médicamenteuse</span></strong></td><td><span class=\"kw-ttt\">IEC</span> surtout ; <span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">6-mercaptopurine</span>, <span class=\"kw-ttt\">furosémide</span>, tétracyclines, œstrogènes, <span class=\"kw-ttt\">valproate</span>, <span class=\"kw-ttt\">chlorothiazide</span>, <span class=\"kw-ttt\">cimétidine</span>, <span class=\"kw-ttt\">méthyldopa</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Ischémique</span></strong></td><td>Contexte de <span class=\"kw-alerte\">réanimation</span> ou post-<span class=\"kw-ttt\">chirurgie</span> (abdominale, cardiaque) : bas débit, souvent grave</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Causes exceptionnelles</span></strong></td><td>PA <span class=\"kw-def\">auto-immune</span> (maladie à <span class=\"kw-chiffre\">IgG</span>4, association <span class=\"kw-def\">MICI</span>) ; PA <span class=\"kw-def\">génétique</span> (gène CFTR de la mucoviscidose) ; <span class=\"kw-def\">pancréas divisum</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Idiopathique</span></strong></td><td><span class=\"kw-chiffre\">10-20 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 45 — Maladies génétiques</em></p>","frequence":1},{"id":"358-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge symptomatique : nutrition des pancréatites ;  analgésie multimodale ; principes de réanimation hydroélectrolytique ; indication de transfert en réanimation ou surveillance continue","contenu":"<p>Le traitement symptomatique est <strong>adapté à la sévérité</strong>. Un traitement étiologique lui est toujours associé (PA biliaire, PEC de l'<span class=\"kw-etio\">alcool</span>, arrêt du <span class=\"kw-etio\">tabac</span>).</p>\n      <table >\n        <thead><tr><th>Axe</th><th>PA non sévère</th><th>PA sévère</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Orientation</td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-clinique\">secteur conventionnel</span></td>\n            <td><span class=\"kw-alerte\">USC</span> si risque d'<span class=\"kw-clinique\">évolution</span> grave (<span class=\"kw-def\">comorbidités</span>, <span class=\"kw-bio\">CRP &gt; 150</span>, SRIS persistant) ; <span class=\"kw-alerte\">réanimation</span> si plusieurs défaillances viscérales</td>\n          </tr>\n          <tr>\n            <td>Nutrition</td>\n            <td>Jeûne tant que douleur importante ; <span class=\"kw-ttt\">SNG</span> en aspiration douce si <span class=\"kw-clinique\">vomissements</span> incoercibles ; <span class=\"kw-clinique\">réalimentation orale précoce</span> dès disparition douleur/<span class=\"kw-clinique\">vomissements</span> (<span class=\"kw-chiffre\">48-72 h</span>)</td>\n            <td>Jeûne ; SNG si besoin ; <strong><span class=\"kw-ttt\">nutrition artificielle entérale</span></strong> mise en place très rapidement (<span class=\"kw-chiffre\">&lt; 48 h</span>) — diminue la <span class=\"kw-def\">mortalité</span></td>\n          </tr>\n          <tr>\n            <td>Hydratation</td>\n            <td colspan=\"2\"><span class=\"kw-ttt\">Cristalloïdes</span> pour corriger l'hypovolémie liée au <span class=\"kw-def\">3ᵉ secteur</span> (<span class=\"kw-clinique\">iléus</span>, fuite interstitielle), avec objectif de diurèse normale</td>\n          </tr>\n          <tr>\n            <td>Antalgie</td>\n            <td colspan=\"2\"><span class=\"kw-ttt\">Antalgiques</span> selon l'intensité, privilégier la <span class=\"kw-ttt\">PCA de morphinique</span> ; <strong><span class=\"kw-ci\">AINS contre-indiqués</span></strong> (risque d'infection et d'hémorragie)</td>\n          </tr>\n          <tr>\n            <td>MTEV</td>\n            <td colspan=\"2\"><span class=\"kw-ttt\">Prophylaxie thromboembolique</span> systématique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Antibiothérapie</span></td>\n            <td colspan=\"2\"><strong><span class=\"kw-alerte\">Pas d'antibiothérapie préventive</span></strong> de l'infection de <span class=\"kw-clinique\">nécrose</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Indication de transfert en <span class=\"kw-alerte\">réanimation ou surveillance continue</span> dès l'apparition d'une ou plusieurs <span class=\"kw-alerte\">défaillances viscérales</span>, ou d'un SRIS persistant chez un patient à risque.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":4},{"id":"358-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge étiologique : connaître les principes de prise en charge d’une pancréatite biliaire","contenu":"<p>La prise en charge étiologique d'une <span class=\"kw-etio\">pancréatite biliaire</span> est <strong>essentielle pour prévenir la récidive</strong>.</p>\n      <p><strong><span class=\"kw-clinique\">Extraction des calculs</span> — <span class=\"kw-def\">CPRE</span> + <span class=\"kw-def\">sphinctérotomie endoscopique</span></strong> : objectif = extraction des calculs enclavés dans le <span class=\"kw-clinique\">cholédoque</span>. Le timing dépend de l'existence d'une <span class=\"kw-alerte\">angiocholite</span> associée :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Angiocholite</span> associée ?</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Oui</strong></td><td><span class=\"kw-alerte\">CPRE + sphinctérotomie en urgence &lt; 24 h</span> ; <span class=\"kw-ttt\">antibiothérapie probabiliste</span> + <span class=\"kw-bio\">hémocultures</span>, secondairement adaptée à l'<span class=\"kw-bio\">antibiogramme</span></td></tr>\n          <tr><td><strong>Non</strong></td><td><span class=\"kw-clinique\">CPRE + sphinctérotomie</span> réalisées <span class=\"kw-clinique\">à distance</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Cholécystectomie</span> systématique</strong>, le plus souvent <span class=\"kw-clinique\">avant la reprise de l'alimentation orale</span> :</p>\n      <ul>\n        <li><strong>PA non sévère :</strong> au cours de la <span class=\"kw-clinique\">même hospitalisation</span></li>\n        <li><strong>PA sévère :</strong> souvent <span class=\"kw-clinique\">différée 3 à 6 semaines</span> après l'épisode, selon l'état clinique</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire · 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":2},{"id":"358-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des complications : connaître les principes de prise en charge d’une coulée de nécrose","contenu":"<p>La prise en charge d'une <strong><span class=\"kw-alerte\">coulée de nécrose</span></strong> dépend de son caractère surinfecté ou non :</p>\n      <ul>\n        <li><strong>Coulée non surinfectée :</strong> <span class=\"kw-clinique\">pas de drainage</span>, sauf <span class=\"kw-clinique\">compression biliaire ou digestive symptomatique</span></li>\n        <li><strong>Suspicion de surinfection</strong> (<span class=\"kw-alerte\">coulée de nécrose + fièvre</span>) : <span class=\"kw-clinique\">ponction de la coulée</span> + <span class=\"kw-bio\">hémocultures</span></li>\n        <li><strong>Surinfection confirmée :</strong> <span class=\"kw-ttt\">antibiothérapie à large spectre</span> adaptée à la <span class=\"kw-ttt\">ponction</span> et aux <span class=\"kw-bio\">hémocultures</span></li>\n      </ul>\n      <p><strong>Collections et pseudo-kystes</strong> — traitement <strong>seulement si</strong> : compliqués, de grande taille (<span class=\"kw-chiffre\">&gt; 6 cm</span>), ou ne régressant pas au cours du <span class=\"kw-def\">suivi</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Drainage endoscopique</span> en 1ʳᵉ intention : prothèse <span class=\"kw-ttt\">kysto-gastrique</span> ou <span class=\"kw-ttt\">kysto-duodénale</span>, sous contrôle écho-endoscopique</li>\n        <li><span class=\"kw-clinique\">Chirurgie</span> (dérivation ou résection) en cas d'échec</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Une coulée ou collection de <span class=\"kw-clinique\">nécrose</span> <span class=\"kw-alerte\">non compliquée</span> ne se draine pas systématiquement : le <span class=\"kw-ttt\">drainage</span> est réservé à la surinfection et aux complications mécaniques.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":2},{"id":"358-15","rang":"B","rubrique":"Epidémiologie","titre":"Connaître le pronostic des pancréatites bégnines et sévères, évolution et mortalité","contenu":"<p>Le <span class=\"kw-alerte\">pronostic</span> dépend de la <span class=\"kw-def\">forme anatomoclinique</span> :</p>\n      <table >\n        <thead><tr><th>Forme</th><th><span class=\"kw-def\">Mortalité</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Mortalité globale</span></td><td><span class=\"kw-chiffre\">3-5 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">PA œdémateuse</span> (bénigne)</td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">PA nécrosante</span></td><td><span class=\"kw-chiffre\">10 %</span> (plus élevée si <span class=\"kw-alerte\">surinfection</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Forme grave d'emblée</span></td><td><span class=\"kw-chiffre\">&gt; 50 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> — trois temps du <span class=\"kw-def\">pronostic</span> :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Pronostic</span> initial :</strong> conditionné par <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications immédiates</span> (<span class=\"kw-alerte\">choc</span>, <span class=\"kw-alerte\">détresse</span> respiratoire)</li>\n        <li><strong><span class=\"kw-def\">Pronostic</span> retardé :</strong> lié à la <span class=\"kw-alerte\">surinfection de nécrose</span>, survenant le plus souvent à la <span class=\"kw-chiffre\">2ᵉ-4ᵉ semaine</span></li>\n        <li><strong><span class=\"kw-def\">Pronostic</span> à long terme :</strong> risque d'<span class=\"kw-alerte\">insuffisance pancréatique exocrine ou endocrine</span> (<span class=\"kw-def\">diabète</span>), surtout après une PA sévère</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span></em></p>","frequence":1},{"id":"358-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les deux principales complications tardives d’une pancréatite aiguë","contenu":"<p>Au décours d'une <span class=\"kw-def\">pancréatite aiguë</span>, deux types de complications tardives doivent être connus.</p>\n      <p><strong>1. Collections liquidiennes tardives</strong> — apparition d'une collection <span class=\"kw-chiffre\">&gt; 4 semaines</span> après la PA (<span class=\"kw-chiffre\">10-50 %</span> des cas) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Pseudo-kyste</span></strong></td><td>Liquide pancréatique pur et clair, secondaire à une <span class=\"kw-clinique\">fistule</span> (<span class=\"kw-alerte\">rupture</span> canalaire)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Collection nécrotique organisée</span></strong></td><td>Liquéfaction des foyers de <span class=\"kw-clinique\">nécrose</span>, dans <span class=\"kw-clinique\">les</span> suites d'une <span class=\"kw-alerte\">PA nécrosante</span></td></tr>\n        </tbody>\n      </table>\n      <p>Souvent <span class=\"kw-clinique\">asymptomatiques</span> ; toute recrudescence douloureuse après un intervalle libre doit <span class=\"kw-clinique\">les</span> faire évoquer. Diagnostic par <span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">TDM</span> ; disparition spontanée dans <span class=\"kw-chiffre\">&lt; 50 %</span> des cas.</p>\n      <p><strong>Complications possibles :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Surinfection</span></strong> → <span class=\"kw-def\">abcès pancréatique</span></li>\n        <li><strong>Compression de la <span class=\"kw-clinique\">VBP</span></strong> → <span class=\"kw-clinique\">ictère</span></li>\n        <li><strong>Compression <span class=\"kw-clinique\">gastro-duodénale</span></strong> → <span class=\"kw-ci\">intolérance</span> alimentaire</li>\n        <li><strong>Compression de l'<span class=\"kw-clinique\">axe spléno-portal</span></strong></li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> ou <span class=\"kw-alerte\">hémorragie</span></strong> (organe creux voisin, péritoine, plèvre)</li>\n      </ul>\n      <p><strong>2. Insuffisance pancréatique</strong> — séquelle fonctionnelle à long terme, surtout après une PA sévère : <span class=\"kw-alerte\">insuffisance pancréatique exocrine</span> et <span class=\"kw-alerte\">endocrine</span> (<span class=\"kw-def\">diabète</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 281 — <span class=\"kw-def\">Pancréatite chronique</span> · 247 — <span class=\"kw-def\">Diabète</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence</span> diagnostique et de <span class=\"kw-alerte\">stratification de gravité</span> ; identifier une <span class=\"kw-alerte\">forme nécrosante</span> ou une <span class=\"kw-alerte\">défaillance viscérale</span> d'emblée<br><strong>Fenêtre :</strong> <span class=\"kw-bio\">lipase</span> précoce, maximum en <span class=\"kw-chiffre\">24-48h</span> (peut être &lt; 3N si dosée ≥ <span class=\"kw-chiffre\">48h</span>) ; <span class=\"kw-imagerie\">échographie</span> &lt; <span class=\"kw-chiffre\">48h</span> ; <span class=\"kw-imagerie\">TDM AP</span> à <span class=\"kw-chiffre\">72h</span> du début des douleurs ; <span class=\"kw-ttt\">CPRE + sphinctérotomie</span> &lt; <span class=\"kw-chiffre\">24h</span> si <span class=\"kw-etio\">angiocholite</span><br><strong>1er geste :</strong> diagnostic = <span class=\"kw-clinique\">douleur typique</span> + <span class=\"kw-bio\">lipase &gt; 3N</span> ; <span class=\"kw-ttt\">réanimation hydroélectrolytique</span> par <span class=\"kw-ttt\">cristalloïdes</span> + <span class=\"kw-ttt\">antalgie</span></p>","hospit":"<p><strong>Conventionnel :</strong> <span class=\"kw-etio\">PA non sévère</span> (forme <span class=\"kw-etio\">œdémateuse</span>, <span class=\"kw-chiffre\">70-80%</span>)<br><strong>USC / <span class=\"kw-def\">surveillance</span> continue :</strong> risque d'<span class=\"kw-clinique\">évolution</span> grave — <span class=\"kw-def\">comorbidités</span> ; <span class=\"kw-bio\">CRP &gt; 150 mg/L</span> à <span class=\"kw-chiffre\">J2</span> ; <span class=\"kw-alerte\">SRIS persistant</span><br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> plusieurs <span class=\"kw-alerte\">défaillances viscérales</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Défaillance viscérale</span> au <span class=\"kw-def\">stade</span> initial : <span class=\"kw-clinique\">choc cardiovasculaire</span>, <span class=\"kw-clinique\">SDRA</span>/<span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-clinique\">oligo-anurie</span> (<span class=\"kw-etio\">IRA</span>), <span class=\"kw-alerte\">défaillance</span> neurologique, <span class=\"kw-etio\">CIVD</span></li><li><span class=\"kw-def\">SRIS</span> <span class=\"kw-chiffre\">≥ 2</span> critères : T &lt; 36 ou &gt;<span class=\"kw-chiffre\"> 38 °C</span> ; <span class=\"kw-clinique\">FC &gt; 90/min</span> ; <span class=\"kw-clinique\">FR &gt; 20/min</span> ou <span class=\"kw-bio\">PaCO₂ &lt; 32 mmHg</span> ; <span class=\"kw-bio\">leucocytes &gt; 12</span> ou &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> G/L</span> (ou &gt;<span class=\"kw-chiffre\"> 10%</span> de formes immatures)</li><li><span class=\"kw-clinique\">Grey-Turner</span> (<span class=\"kw-ttt\">infiltration</span> hématique des flancs) et <span class=\"kw-clinique\">Cullen</span> (péri-ombilicale) → forme <span class=\"kw-etio\">nécrosante</span></li><li><span class=\"kw-bio\">CRP &gt; 150 mg/L</span> à <span class=\"kw-chiffre\">J2</span> : marqueur <span class=\"kw-ttt\">biologique</span> le plus fiable de gravité</li><li><span class=\"kw-radio\">CTSI (Balthazar modifié) ≥ 4</span> au <span class=\"kw-imagerie\">scanner</span> (modérément sévère 4-6, grave 7-10)</li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-alerte\">obésité</span> (FR indépendant de gravité)</li><li>NON pronostiques : douleur, <span class=\"kw-clinique\">vomissement</span>, <span class=\"kw-clinique\">iléus</span>, lipasémie, hyperleucocytose</li></ul>","principes":"<p>PEC symptomatique + étiologique menées en parallèle ; jamais d'<span class=\"kw-ci\">antibioprophylaxie</span> de la <span class=\"kw-clinique\">nécrose</span>.</p><ul><li><span class=\"kw-ttt\">Hydratation</span> : <span class=\"kw-ttt\">cristalloïdes</span> pour obtenir une diurèse normale (corriger l'hypovolémie du <span class=\"kw-clinique\">3ème secteur</span>)</li><li><span class=\"kw-ttt\">Antalgie multimodale</span> : privilégier la <span class=\"kw-ttt\">PCA de morphinique</span> ; <span class=\"kw-ci\">AINS contre-indiqués</span> (risque d'infection et d'hémorragie)</li><li><span class=\"kw-ttt\">Nutrition</span> : jeûne tant que douleur abdominale ; réalimentation orale précoce en <span class=\"kw-chiffre\">48-72h</span> ; si sévère <span class=\"kw-ttt\">nutrition entérale</span> &lt; <span class=\"kw-chiffre\">48h</span> (↓ la <span class=\"kw-def\">mortalité</span>) ; <span class=\"kw-ttt\">SNG</span> en aspiration douce si <span class=\"kw-clinique\">vomissements</span> incoercibles</li><li><span class=\"kw-ttt\">Prophylaxie thromboembolique</span> (MTEV)</li><li>PA <span class=\"kw-etio\">biliaire</span> : <span class=\"kw-ttt\">CPRE + sphinctérotomie endoscopique</span> &lt; <span class=\"kw-chiffre\">24h</span> si <span class=\"kw-etio\">angiocholite</span> associée ; <span class=\"kw-ttt\">cholécystectomie</span> systématique (même <span class=\"kw-alerte\">hospitalisation</span> si non sévère, différée <span class=\"kw-chiffre\">3-6 semaines</span> si sévère)</li><li><span class=\"kw-etio\">Coulée de nécrose</span> non surinfectée : pas de <span class=\"kw-ttt\">drainage</span>, sauf compression biliaire ou digestive symptomatique</li><li><span class=\"kw-etio\">Surinfection de nécrose</span> (coulée + <span class=\"kw-clinique\">fièvre</span>) : <span class=\"kw-ttt\">ponction</span> de la coulée + <span class=\"kw-bio\">hémocultures</span>, puis <span class=\"kw-ttt\">ATB à large spectre</span> adaptée secondairement</li><li><span class=\"kw-etio\">Pseudo-kyste</span> : <span class=\"kw-ttt\">drainage</span> (endoscopique en <span class=\"kw-chiffre\">1ère intention</span>) seulement si compliqué, de grande taille (&gt; <span class=\"kw-chiffre\">6 cm</span>) ou ne régressant pas</li></ul>","suivi":"<p><strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM AP</span> à <span class=\"kw-chiffre\">72h</span> du début des douleurs pour le <span class=\"kw-radio\">CTSI</span> (évaluation de la sévérité)<br><strong>Surinfection de <span class=\"kw-clinique\">nécrose</span> :</strong> survient <span class=\"kw-chiffre\">2-4 semaines</span> après le début de l'<span class=\"kw-alerte\">hospitalisation</span> — <span class=\"kw-clinique\">fièvre</span>, majoration du <span class=\"kw-alerte\">SRIS</span>, nouvelles défaillances viscérales<br><strong>Complications tardives :</strong> <span class=\"kw-etio\">pseudo-kyste</span> et <span class=\"kw-etio\">collection nécrotique organisée</span> (collections &gt; <span class=\"kw-chiffre\">4 semaines</span>)<br><strong>Long terme :</strong> <span class=\"kw-etio\">insuffisance pancréatique exocrine ou endocrine</span> (<span class=\"kw-etio\">diabète</span>), surtout si PA sévère</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/52.%20Pancr%C3%A9atite%20aigu%C3%AB.pdf","label":"CeMIR — 52. pancréatite aiguë"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur pancréatique typique — Épigastrique transfixiante, position en chien de fusil","detail":"<h4>CAT — <span class=\"kw-clinique\">pancréatite aiguë</span> : du diagnostic à l'orientation — <span class=\"kw-def\">Diagnostic positif</span> (<span class=\"kw-bio\">lipase</span>) puis stratification de gravité → niveau de soins</h4>","branches":[{"to":"q-lipase","label":"Suspicion de pancréatite aiguë","color":"blue"}]},{"id":"q-lipase","kind":"decision","label":"Lipase &gt; 3N ? — Maximum en 24-48h ; peut être &lt; 3N si dosée ≥ 48h","branches":[{"to":"t-doute","label":"Non / douleur atypique","color":"blue"},{"to":"q-defaillance","label":"Oui — diagnostic posé","color":"green"}]},{"id":"t-doute","kind":"terminal","label":"TDM AP injectée — lever le doute","color":"blue","detail":"<h4>Conduite</h4><ul><li>Indiquée si doute diagnostique (douleur atypique, malade vu après le pic de lipasémie)</li><li>But : confirmer la PA et/ou éliminer un <span class=\"kw-def\">diagnostic différentiel</span></li></ul><h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-etio\">Ulcère gastro-duodénal perforé</span> (pneumopéritoine)</li><li><span class=\"kw-etio\">IDM inférieur</span> (écarté par l'<span class=\"kw-imagerie\">ECG</span>)</li><li><span class=\"kw-etio\">Infarctus mésentérique</span></li><li><span class=\"kw-etio\">Rupture d'anévrisme de l'aorte abdominale</span></li><li><span class=\"kw-etio\">Pneumopathie</span></li><li><span class=\"kw-etio\">Péritonite biliaire</span></li></ul>"},{"id":"q-defaillance","kind":"decision","label":"Défaillance viscérale d'emblée ? — Choc, SDRA, oligo-anurie, CIVD, atteinte neurologique","branches":[{"to":"t-rea","label":"Oui (choc, SDRA, oligo-anurie, CIVD)","color":"red"},{"to":"q-gravite","label":"Non","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Transfert en réanimation","color":"red","detail":"<h4>Conduite</h4><ul><li>Forme grave d'emblée (<span class=\"kw-def\">mortalité</span> &gt;<span class=\"kw-chiffre\"> 50%</span>)</li><li><span class=\"kw-ttt\">Réanimation hydroélectrolytique</span> par <span class=\"kw-ttt\">cristalloïdes</span></li><li><span class=\"kw-ttt\">Nutrition entérale</span> précoce &lt;<span class=\"kw-chiffre\"> 48h</span></li><li><span class=\"kw-ttt\">Antalgie</span> (PCA morphinique) ; <span class=\"kw-ci\">AINS contre-indiqués</span></li><li>Pas d'<span class=\"kw-ci\">antibioprophylaxie</span> de la <span class=\"kw-clinique\">nécrose</span></li></ul><h4>Critères</h4><ul><li><span class=\"kw-alerte\">Plusieurs défaillances viscérales</span> : <span class=\"kw-alerte\">choc</span> cardiovasculaire, <span class=\"kw-alerte\">SDRA</span>, oligo-anurie/IRA, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-alerte\">défaillance</span> neurologique</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Critère de gravité présent ? — SRIS persistant, CRP, CTSI, terrain","branches":[{"to":"t-usc","label":"Oui (SRIS, CRP &gt; 150 J2, CTSI ≥ 4)","color":"amber"},{"to":"t-conv","label":"Non","color":"green"}]},{"id":"t-usc","kind":"terminal","label":"USC / surveillance continue","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> rapprochée (risque d'aggravation secondaire à distance)</li><li><span class=\"kw-ttt\">Réanimation hydroélectrolytique</span>, <span class=\"kw-ttt\">antalgie multimodale</span></li><li><span class=\"kw-ttt\">Prophylaxie thromboembolique</span></li></ul><h4><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></h4><ul><li><span class=\"kw-alerte\">SRIS persistant</span></li><li><span class=\"kw-bio\">CRP &gt; 150 mg/L</span> à <span class=\"kw-chiffre\">J2</span> (marqueur le plus fiable)</li><li><span class=\"kw-radio\">CTSI ≥ 4</span> (<span class=\"kw-imagerie\">TDM</span> à<span class=\"kw-chiffre\"> 72h</span>)</li><li><span class=\"kw-def\">Comorbidités</span>, <span class=\"kw-alerte\">obésité</span></li></ul>"},{"id":"t-conv","kind":"terminal","label":"Hospitalisation en secteur conventionnel","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">PA non sévère</span> (forme œdémateuse,<span class=\"kw-chiffre\"> 70-80%</span>)</li><li>Jeûne tant que douleur ; réalimentation orale précoce <span class=\"kw-chiffre\">48-72h</span></li><li><span class=\"kw-ttt\">Antalgie</span>, <span class=\"kw-ttt\">hydratation</span> par cristalloïdes, <span class=\"kw-ttt\">prophylaxie MTEV</span></li></ul><h4>Bilan étiologique</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> &lt;<span class=\"kw-chiffre\"> 48h</span>, <span class=\"kw-bio\">bilan hépatique</span>/lipidique, <span class=\"kw-bio\">calcémie</span></li><li>Si <span class=\"kw-etio\">origine biliaire</span> : <span class=\"kw-ttt\">cholécystectomie</span> au cours de la même <span class=\"kw-alerte\">hospitalisation</span></li></ul>"}]},"cards":[{"i":"6fc3e999db4c","n":358,"o":"358-1","u":"Définition","t":"Connaître la définition de la pancréatite aiguë","q":"Quelle est la définition de la pancréatite aiguë ?","a":"<p>La pancréatite aiguë est une <strong>inflammation aiguë du pancréas</strong>.</p>"},{"i":"9c62a6b006c0","n":358,"o":"358-1","u":"Définition","t":"Connaître la définition de la pancréatite aiguë","q":"Quelles sont les trois étapes physiopathologiques principales de la pancréatite aiguë ?","a":"<ul><li><strong>Agression du parenchyme pancréatique</strong> et/ou obstacle à l'excrétion du suc pancréatique.</li><li><strong>Activation intra-pancréatique des enzymes</strong> (conversion du trypsinogène en trypsine) libérées en excès.</li><li><strong>Autodigestion pancréatique</strong>, entraînant une inflammation voire une nécrose de la glande et des tissus avoisinants.</li></ul>"},{"i":"c94aa19c8a76","n":358,"o":"358-1","u":"Définition","t":"Connaître la définition de la pancréatite aiguë","q":"Quelles sont les deux formes anatomocliniques de la pancréatite aiguë ?","a":"<ul><li>La <strong>pancréatite aiguë œdémateuse</strong> (ou bénigne), représentant 70-80% des cas avec une mortalité inférieure à 1%.</li><li>La <strong>pancréatite aiguë nécrosante</strong>, représentant 20-30% des cas avec une mortalité de 10% (plus élevée si surinfection de nécrose).</li></ul>"},{"i":"d9dfb704fc0b","n":358,"o":"358-1","u":"Définition","t":"Connaître la définition de la pancréatite aiguë","q":"Quelle est la mortalité globale de la pancréatite aiguë ?","a":"<p>La mortalité globale de la pancréatite aiguë est de <strong>3 à 5 %</strong>.</p>"},{"i":"1f1924461326","n":358,"o":"358-10","u":"Étiologies","t":"Savoir identifier les deux principales causes de pancréatite aiguë","q":"Quels sont les arguments clinico-biologiques évoquant une origine alcoolique devant une pancréatite aiguë ?","a":"<p>Les arguments évoquant une origine alcoolique sont :</p><ul><li>Un terrain : homme d'environ <strong>40 ans</strong>, consommation d'alcool > <strong>100 g/jour</strong> (environ 10 verres standard) depuis plus de <strong>10 ans</strong>. Le tabac est un cofacteur de sévérité.</li><li>Des signes biologiques évocateurs : augmentation du VGM (Volume Globulaire Moyen), augmentation des γ-GT, cytolyse hépatique prédominant sur les <strong>ASAT > ALAT</strong>.</li><li>La pancréatite aiguë peut correspondre à une poussée inaugurale de pancréatite chronique calcifiante dans 90% des cas.</li></ul>"},{"i":"8b31a0ddc1f8","n":358,"o":"358-10","u":"Étiologies","t":"Savoir identifier les deux principales causes de pancréatite aiguë","q":"Dans le cadre d'une pancréatite aiguë d'origine biliaire, quel est le mécanisme déclenchant ?","a":"<p>Le mécanisme déclenchant est la <strong>migration d'un calcul biliaire</strong> dans le cholédoque ou la voie biliaire principale (VBP).</p>"},{"i":"e2c69849491d","n":358,"o":"358-10","u":"Étiologies","t":"Savoir identifier les deux principales causes de pancréatite aiguë","q":"Quelles sont les deux principales causes de pancréatite aiguë ?","a":"<p>Les deux principales causes, représentant <strong>80 %</strong> des cas de pancréatite aiguë, sont :</p><ul><li>La <strong>lithiase biliaire</strong> (40 %)</li><li>L'<strong>alcool</strong> (40 %)</li></ul>"},{"i":"1b44070b5281","n":358,"o":"358-2","u":"Identifier une urgence","t":"Savoir identifier les situations de gravité immédiate de la pancréatite aiguë","q":"Quelle est l'importance du suivi clinique dans une pancréatite aiguë ?","a":"<p>Une pancréatite aiguë peut être grave d'emblée ou <strong>s'aggraver secondairement</strong>, parfois plusieurs jours à semaines après le début. La <strong>surveillance</strong> clinique prolongée est donc essentielle et ne s'arrête pas à la phase initiale.</p>"},{"i":"41ddbec28498","n":358,"o":"358-2","u":"Identifier une urgence","t":"Savoir identifier les situations de gravité immédiate de la pancréatite aiguë","q":"Quelles sont les défaillances viscérales à reconnaître en urgence dans le cadre d'une pancréatite aiguë grave ?","a":"<ul><li><strong>Choc cardiovasculaire</strong></li><li><strong>SDRA</strong> (détresse respiratoire aiguë)</li><li><strong>Oligo-anurie / insuffisance rénale aiguë</strong></li><li>Défaillance neurologique</li><li><strong>CIVD</strong> (Coagulation IntraVasculaire Disséminée)</li></ul>"},{"i":"818f67d59a1e","n":358,"o":"358-2","u":"Identifier une urgence","t":"Savoir identifier les situations de gravité immédiate de la pancréatite aiguë","q":"Quels sont les signes cutanés marquant une gravité immédiate et une forme nécrosante hémorragique de pancréatite aiguë ?","a":"<ul><li>Le <strong>signe de Grey-Turner</strong> : infiltration hématique des flancs.</li><li>Le <strong>signe de Cullen</strong> : infiltration hématique péri-ombilicale.</li></ul>"},{"i":"9c4576913d78","n":358,"o":"358-2","u":"Identifier une urgence","t":"Savoir identifier les situations de gravité immédiate de la pancréatite aiguë","q":"Comment définit-on une pancréatite aiguë grave d'emblée ?","a":"<p>Une pancréatite aiguë est qualifiée de grave d'emblée par la présence d'une <strong>défaillance viscérale</strong> dès le <strong>stade initial</strong> de la poussée.</p>"},{"i":"1e2606a66c03","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"Le dosage de l'amylase est-il recommandé pour le diagnostic de pancréatite aiguë ?","a":"<p>Non, le dosage de l'amylase pour le diagnostic de pancréatite aiguë <strong>doit être abandonné</strong> au profit de la lipasémie.</p>"},{"i":"95839455f464","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"Quelles sont les caractéristiques sémiologiques de la douleur typique de la pancréatite aiguë ?","a":"<ul><li><strong>Siège</strong> : Épigastrique, hypochondre gauche, sus-ombilical.</li><li><strong>Irradiation</strong> : Postérieure transfixiante, hémi-ceinture gauche costo-lombaire.</li><li><strong>Type</strong> : Torsion, arrachement, broiement en coup de poignard.</li><li><strong>Début</strong> : Rapidement progressif.</li><li><strong>Horaire</strong> : Aiguë, intense, insomniante, durant plusieurs heures à jours.</li><li><strong>Attitude antalgique</strong> : Position en chien de fusil (antéflexion du tronc, compression de l'épigastre).</li><li><strong>Facteurs déclenchants</strong> : Alimentation, alcool, certains médicaments.</li></ul>"},{"i":"a596d5b3aa39","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"Quelle est la valeur diagnostique de la lipasémie dans la pancréatite aiguë ?","a":"<p>Une douleur typique associée à une <strong>lipase > 3N</strong> suffit au diagnostic de pancréatite aiguë. Son élévation est précoce, parfois fugace, avec un maximum en <strong>24-48 h</strong>. Elle peut être inférieure à 3N si le dosage est réalisé <strong>≥ 48 h</strong> après le début des douleurs.</p>"},{"i":"b7f00a6d9c82","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"La lipasémie a-t-elle une valeur pronostique dans la pancréatite aiguë ?","a":"<p>Non, la lipasémie n'a <strong>aucune valeur pronostique</strong> dans la pancréatite aiguë. Il n'existe pas de corrélation entre le taux de lipase et la gravité de la pathologie.</p>"},{"i":"ba2bcafaf44c","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"Quels sont les principaux signes associés à la douleur dans la pancréatite aiguë ?","a":"<ul><li><strong>Vomissements</strong> (50 %) : alimentaires puis bilieux.</li><li><strong>Iléus réflexe</strong> (30 %) : arrêt des matières et des gaz (rarement complet), météorisme sonore.</li><li><strong>Signes généraux</strong> : fièvre, tachycardie, hypotension.</li><li><strong>Défense abdominale</strong> : possible, diffuse ou localisée à l'épigastre.</li></ul>"},{"i":"d1a0f82d655d","n":358,"o":"358-3","u":"Diagnostic positif","t":"Savoir faire le diagnostic de pancréatite aiguë : sémiologie de la douleur pancréatique et biologie (lipase)","q":"Comment établit-on le diagnostic positif de pancréatite aiguë ?","a":"<p>Le diagnostic positif de pancréatite aiguë repose sur l'association d'une <strong>douleur abdominale typique</strong> et d'une <strong>lipasémie</strong> élevée.</p>"},{"i":"1dbec7028686","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Quels sont les diagnostics différentiels vasculaires majeurs à évoquer devant une douleur épigastrique intense et leurs signes distinctifs ?","a":"<ul><li>L'<strong>infarctus mésentérique</strong> : souvent des <strong>antécédents vasculaires</strong> et des <strong>signes TDM spécifiques</strong>.</li><li>La <strong>rupture d'anévrisme de l'aorte abdominale</strong> : présence d'une <strong>masse battante</strong>, un <strong>collapsus</strong>, et confirmée par une <strong>angio-TDM</strong>.</li></ul>"},{"i":"625837cc40a4","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Quels sont les éléments clés permettant de différencier un ulcère gastro-duodénal (UGD) perforé ou non d'une pancréatite aiguë ?","a":"<ul><li>Les <strong>antécédents d'UGD</strong>.</li><li>Un <strong>début très brutal</strong> de la douleur.</li><li>La présence d'un <strong>pneumopéritoine</strong> à l'imagerie.</li></ul>"},{"i":"a017d38aa90a","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Comment différencier un infarctus du myocarde inférieur d'une pancréatite aiguë devant une douleur épigastrique ?","a":"<p>L'<strong>électrocardiogramme (ECG)</strong> est l'examen clé pour écarter un infarctus du myocarde inférieur, qui peut se manifester par une douleur projetée à l'épigastre.</p>"},{"i":"b17811991c5a","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Quels diagnostics sont à considérer devant une douleur épigastrique intense avec des signes de péritonite, et comment les différencier d'une pancréatite aiguë ?","a":"<ul><li>Une <strong>péritonite biliaire</strong>, caractérisée par une <strong>contracture</strong> et un <strong>syndrome péritonéal</strong>.</li><li>Ces diagnostics sont généralement éliminés par la lipasémie normale, et confirmés par l'imagerie.</li></ul>"},{"i":"e679501b854d","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Pourquoi et comment doit-on toujours considérer une pneumopathie comme diagnostic différentiel d'une douleur épigastrique intense ?","a":"<p>Une <strong>pneumopathie</strong>, particulièrement des bases pulmonaires, peut mimer une douleur abdominale haute par projection. Il faut toujours penser à l'<strong>examen pleuro-pulmonaire</strong> et réaliser une <strong>radiographie thoracique</strong> devant une douleur épigastrique.</p>"},{"i":"f0f5cc26d618","n":358,"o":"358-4","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des douleurs abdominales","q":"Quelle est l'aide diagnostique clé pour écarter de nombreux diagnostics différentiels devant une douleur épigastrique intense suspecte de pancréatite aiguë ?","a":"<p>La mesure de la <strong>lipasémie</strong> permet d'écarter de nombreux diagnostics différentiels, car une élévation significative est très suggestive de pancréatite aiguë.</p>"},{"i":"073cff3cd361","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Quel piège classique concerne le calcul du délai pour la réalisation de la TDM abdomino-pelvienne dans la pancréatite aiguë ?","a":"<p>Le délai de la TDM se compte à partir du <strong>début des douleurs</strong> et non à partir du début de la prise en charge. Une TDM faite trop tôt sous-estimerait l'étendue de la nécrose.</p>"},{"i":"22465490527c","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Pourquoi la TDM abdomino-pelvienne ne peut-elle pas remplacer l'échographie abdominale pour la recherche de lithiase biliaire dans la pancréatite aiguë ?","a":"<p>La TDM abdomino-pelvienne est <strong>moins performante</strong> que l'échographie abdominale pour la détection de la lithiase biliaire.</p>"},{"i":"4fb9f3f75da9","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Quelles sont les indications limitées de la TDM abdomino-pelvienne dans la pancréatite aiguë ?","a":"<p>Les indications de la TDM abdomino-pelvienne sont limitées et incluent :</p><ul><li>Un <strong>doute diagnostique</strong>.</li><li>L'<strong>évaluation des formes sévères</strong>.</li><li>L'<strong>évaluation de la gravité</strong> de la pancréatite aiguë.</li></ul>"},{"i":"88a4fccdf2da","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Quels sont les objectifs de la TDM abdomino-pelvienne lorsqu'elle est indiquée dans le cadre d'une pancréatite aiguë ?","a":"<p>Les objectifs de la TDM abdomino-pelvienne sont :</p><ul><li>L'évaluation du <strong>score CTSI</strong> (Contrast-Enhanced CT Severity Index) pour le diagnostic positif et la sévérité.</li><li>La recherche de complications telles que l'<strong>ascite</strong>, l'<strong>épanchement pleural</strong>, une <strong>hémorragie</strong>, une <strong>fistule</strong> ou une <strong>perforation d'organe creux</strong>.</li></ul>"},{"i":"bacb68594a07","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Quels sont les objectifs principaux de l'échographie abdominale dans le bilan d'une pancréatite aiguë ?","a":"<p>Les objectifs de l'échographie abdominale sont :</p><ul><li>L'<strong>orientation étiologique</strong>, notamment la recherche d'une lithiase vésiculaire.</li><li>La recherche d'une <strong>dilatation ou lithiase de la VBP</strong> (Voie Biliaire Principale).</li></ul>"},{"i":"c47aa4ae924e","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"Quelle est l'indication et le moment idéal pour réaliser une échographie abdominale devant une pancréatite aiguë ?","a":"<p>L'échographie abdominale est à réaliser de manière <strong>systématique</strong>, idéalement <strong>moins de 48 heures</strong> après le début des douleurs.</p>"},{"i":"da899450f2ea","n":358,"o":"358-7","u":"Examens complémentaires","t":"Connaître les indications et les objectifs des examens d’imagerie devant une pancréatite aiguë","q":"À quel moment doit être réalisée une TDM abdomino-pelvienne en cas de pancréatite aiguë et pourquoi ce délai est-il important ?","a":"<p>La TDM abdomino-pelvienne ne doit <strong>pas être réalisée au diagnostic initial</strong>. Elle doit être différée de <strong>72 à 96 heures</strong> après le début des douleurs. Ce délai est crucial car une TDM réalisée trop tôt <strong>sous-estime</strong> l'étendue de la nécrose.</p>"}]};